async discoverSessionMcp(session, signal, clients) {
  const mounted = new Map();
  const services = new Set();
  for (const server of session.mcpServers) {
    if (!server.command || server.type || services.has(server.name)) {
      throw new Error("Snow ACP requires uniquely named stdio MCP servers");
    }
    services.add(server.name);
    const client = createMCPClient(server.name);
    clients.add(client);
    this.activeMcpClients.add(client);
    const discoverySignal = AbortSignal.any([signal, AbortSignal.timeout(10000)]);
    discoverySignal.throwIfAborted();
    let onAbort;
    try {
      await Promise.race([
        new Promise((_, reject) => {
          onAbort = () => reject(discoverySignal.reason);
          discoverySignal.addEventListener("abort", onAbort, { once: true });
        }),
        client.connect(new StdioClientTransport({
          command: server.command,
          args: server.args,
          cwd: session.cwd,
          env: Object.fromEntries(server.env.map(({ name, value }) => [name, value])),
          stderr: "ignore"
        }))
      ]);
    } finally {
      discoverySignal.removeEventListener("abort", onAbort);
    }
    let cursor;
    do {
      const page = await client.listTools(cursor ? { cursor } : {}, { signal: discoverySignal });
      for (const tool of page.tools) {
        const name = `${server.name}-${tool.name}`;
        if (mounted.has(name) || !/^[a-zA-Z0-9_-]{1,64}$/.test(name)) {
          throw new Error("Invalid or duplicate Snow ACP MCP tool name: " + name);
        }
        mounted.set(name, {
          client,
          toolName: tool.name,
          serviceName: server.name,
          definition: {
            type: "function",
            function: { name, description: tool.description, parameters: tool.inputSchema }
          }
        });
      }
      cursor = page.nextCursor;
    } while (cursor);
  }
  return mounted;
}
async closeSessionMcp(clients) {
  await Promise.allSettled(Array.from(clients, async (client) => {
    if (this.activeMcpClients.delete(client)) {
